ottom strong{display:block;font:12px 'DM Mono';margin-top:5px}.actions{display:flex;gap:6px}.actions button,.open{font-size:11px;padding:8px 10px}.open{border:1px solid var(--line);border-radius:8px;cursor:pointer}.open input{display:none}.examples{padding-top:20px}.examples>div:first-child{display:flex;justify-content:space-between;align-items:center}.examples button{border:0;background:none;font-size:11px;color:var(--green);padding:0}.exampleList{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.exampleList button{font-size:11px;padding:8px 11px}.exampleList button.selected{background:#e8f1eb;border-color:#c6ded0;color:var(--green)}#modal:empty{display:none}
