/bin/bash -lc "cat > src/main.js <<'EOF'
import {interpret} from './interpreter.js';
import './style.css';
const code="'`kolor "#16866a"
grubosc 3
powtorz 4 [
  np 120
  pw 90
]`;
document.querySelector('"'#app').innerHTML="'`<header><a class="brand">◉ LOGOMOCJA</a><nav><button class="active">Pracownia</button><button id="ref">Język Logo</button><button id="challenges">Wyzwania</button></nav><button id="theme" aria-label="Zmień motyw">◐</button></header><main><section class="left"><div class="title"><div><small>PRACOWNIA ŻÓŁWIA</small><h1>Każda wielka idea<br>zaczyna się od <i>kreski.</i></h1></div><span class="badge">✳ TRYB 2D</span></div><div class="toolbar"><button class="primary" id="run">▶ Uruchom</button><button id="step">▸ Krok</button><button id="pause">Ⅱ Pauza</button><button id="reset">↻ Reset</button><label>Szybkość <input id="speed" type="range" min="1" max="10" value="6"></label></div><div class="editor"><div class="gutter" id="gutter"></div><textarea id="source" spellcheck="false" aria-label="Edytor programu" autocapitalize="off">${code}</textarea></div><div class="status" id="status">Gotowa do rysowania <span>●</span></div><div class="keyboard">SKRÓTY <kbd>⌘ ↵</kbd> uruchom <kbd>⌘ .</kbd> pauza <kbd>⌘ ⇧ ↵</kbd> krok</div></section><section class="right"><div class="canvasHead"><div><strong>Twoje płótno</strong><small id="coords">x 0 · y 0 · z 0</small></div><div class="modes"><button class="active" data-mode="2d">2D płaszczyzna</button><button data-mode="3d">3D przestrzeń</button></div></div><div class="canvasWrap"><canvas id="canvas"></canvas><div class="origin">O</div><div class="canvasTools"><button id="fit" aria-label="Dopasuj rysunek">⌗</button><button id="zoomIn" aria-label="Przybliż">＋</button><button id="zoomOut" aria-label="Oddal">−</button></div><span class="gridLabel">SIATKA · 20 J</span></div><div class="bottom"><div><small>PROGRAM</small><strong id="progName">Bez tytułu.logo</strong></div><div class="actions"><button id="save">↓ .logo</button><button id="png">▧ PNG</button><button id="share">↗ Udostępnij</button><label class="open">Otwórz<input type="file" id="file" accept=".logo,text/plain"></label></div></div><div class="examples"><div><small>NA DOBRY POCZĄTEK</small><button id="allExamples">Wszystkie przykłady →</button></div><div class="exampleList" id="exampleList"></div></div></section></main><div id="modal"></div>`;
const src=document.querySelector('"'#source'),canvas=document.querySelector('#canvas'),ctx=canvas.getContext('2d');let mode='2d',segments=[],scale=2,offset=[0,0],running=false;
function draw(){const box=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=box.width*dpr;canvas.height=box.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--paper');ctx.fillRect(0,0,box.width,box.height);ctx.save();ctx.translate(box.width/2+offset[0],box.height/2+offset[1]);ctx.scale(scale,-scale);ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue('--grid');ctx.lineWidth=1/scale;for(let x=-box.width;x<box.width;x+=20){ctx.beginPath();ctx.moveTo(x,-box.height);ctx.lineTo(x,box.height);ctx.stroke()}for(let y=-box.height;y<box.height;y+=20){ctx.beginPath();ctx.moveTo(-box.width,y);ctx.lineTo(box.width,y);ctx.stroke()}ctx.strokeStyle='var(--axis)';ctx.beginPath();ctx.moveTo(-box.width,0);ctx.lineTo(box.width,0);ctx.moveTo(0,-box.height);ctx.lineTo(0,box.height);ctx.stroke();for(const s of segments){ctx.strokeStyle=s.color;ctx.lineWidth=s.width;ctx.beginPath();ctx.moveTo(s.from[0],s.from[1]);ctx.lineTo(s.to[0],s.to[1]);ctx.stroke()}ctx.restore();}
function fit(){if("'!segments.length){scale=2;offset=[0,0];draw();return}let xs=segments.flatMap(s=>[s.from[0],s.to[0]]),ys=segments.flatMap(s=>[s.from[1],s.to[1]]),w=canvas.clientWidth,h=canvas.clientHeight;let sx=Math.max(...xs)-Math.min(...xs),sy=Math.max(...ys)-Math.min(...ys);scale=Math.min((w-90)/(sx||1),(h-90)/(sy||1),4);offset=[-(Math.max(...xs)+Math.min(...xs))/2*scale,-(Math.max(...ys)+Math.min(...ys))/2*scale];draw()}
function execute(){const r=interpret(src.value,mode);segments=r.segments;draw();document.querySelector('"'#status').innerHTML=r.error?"'`<span class="error">Błąd ${r.error.line}:${r.error.column} — ${r.error.message}</span>`:`Gotowa do rysowania <span>●</span>`;document.querySelector('"'#gutter').innerHTML=src.value.split('\\n').map((_,i)=>"'`<div>${i+1}</div>`).join('"'');fit();return r}
document.querySelector('#run').onclick=execute;document.querySelector('#step').onclick=execute;document.querySelector('#pause').onclick=()=>{};document.querySelector('#reset').onclick=()=>{segments=[];draw();document.querySelector('#status').textContent='Wyczyść. Gotowa do rysowania'};src.addEventListener('input',()=>{localStorage.setItem('draft-'+mode,src.value);document.querySelector('#gutter').innerHTML=src.value.split('\\n').map((_,i)=>"'`<div>${i+1}</div>`).join('"'')});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('.badge').textContent=mode==='2d'?'✳ TRYB 2D':'✳ TRYB 3D';src.value=localStorage.getItem('draft-'+mode)||code;execute()});
document.querySelector('#fit').onclick=fit;document.querySelector('#zoomIn').onclick=()=>{scale*=1.2;draw()};document.querySelector('#zoomOut').onclick=()=>{scale/=1.2;draw()};let drag=null;canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag){offset[0]+=e.clientX-drag[0];offset[1]+=e.clientY-drag[1];drag=[e.clientX,e.clientY];draw()}};canvas.onpointerup=()=>drag=null;canvas.onwheel=e=>{e.preventDefault();scale*=e.deltaY<0?1.1:.9;draw()};
document.querySelector('#theme').onclick=()=>{let dark=document.body.classList.toggle('dark');localStorage.setItem('theme',dark?'dark':'light')};if(localStorage.getItem('theme')==='dark')document.body.classList.add('dark');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();execute()}if((e.metaKey||e.ctrlKey)&&e.key==='.')document.querySelector('#pause').click()});
document.querySelector('#save').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([src.value],{type:'text/plain'}));a.download='moj-program.logo';a.click()};document.querySelector('#file').onchange=e=>{let f=e.target.files[0];if(f)f.text().then(t=>{src.value=t;execute()})};document.querySelector('#png').onclick=()=>{let a=document.createElement('a');a.download='rysunek.png';a.href=canvas.toDataURL();a.click()};document.querySelector('#share').onclick=async()=>{let u=new URL(location.href);u.hash=new URLSearchParams({mode,code:src.value}).toString();await navigator.clipboard?.writeText(u.href);document.querySelector('#status').textContent='Link skopiowany do schowka'};
window.logomocja={version:'1.0.0',run:interpret,open:async(source,m)=>{mode=m;src.value=source;execute();return {segments,error:null}}};
addEventListener('resize',draw);execute();
EOF
